using Autodesk.AutoCAD.ApplicationServices;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Geometry;
using Autodesk.AutoCAD.Runtime;

public class Commands
{
    [CommandMethod("ADDLINE")]
    public void AddLine()
    {
        Document doc = Application.DocumentManager.MdiActiveDocument;
        Database db = doc.Database;
        using (Transaction tr = db.TransactionManager.StartTransaction())
        {
            var bt  = (BlockTable)tr.GetObject(db.BlockTableId, OpenMode.ForRead);
            var btr = (BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace], OpenMode.ForWrite);
            using (var ln = new Line(new Point3d(0, 0, 0), new Point3d(100, 100, 0)))
            {
                ln.Layer = "0";
                btr.AppendEntity(ln);
                tr.AddNewlyCreatedDBObject(ln, true);
            }
            tr.Commit();
        }
        doc.Editor.WriteMessage("\nLine created.");
    }
}

// ObjectARX sketch
void createLine()
{
    AcGePoint3d p1, p2;
    if (acedGetPoint(NULL, _T("\nFirst point: "), asDblArray(p1)) != RTNORM) return;
    if (acedGetPoint(asDblArray(p1), _T("\nSecond point: "), asDblArray(p2)) != RTNORM) return;

    AcDbLine *pLine = new AcDbLine(p1, p2);
    AcDbBlockTable *pBlockTable = NULL;
    acdbHostApplicationServices()->workingDatabase()->getBlockTable(pBlockTable, AcDb::kForRead);
    AcDbBlockTableRecord *pRec = NULL;
    pBlockTable->getAt(ACDB_MODEL_SPACE, pRec, AcDb::kForWrite);
    pBlockTable->close();
    pRec->appendAcDbEntity(pLine);
    pRec->close();
    pLine->close();
}
